import{_ as t,c as l,o as e,a4 as o}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"Photoshop","description":"","frontmatter":{},"headers":[],"relativePath":"tools/photoshop.md","filePath":"tools/photoshop.md"}'),i={name:"tools/photoshop.md"},a=o('<h1 id="photoshop" tabindex="-1">Photoshop <a class="header-anchor" href="#photoshop" aria-label="Permalink to &quot;Photoshop&quot;">​</a></h1><p>[toc]</p><h2 id="工作区" tabindex="-1">工作区 <a class="header-anchor" href="#工作区" aria-label="Permalink to &quot;工作区&quot;">​</a></h2><ul><li>历史记录</li><li>信息</li><li>导航器</li><li>图层</li><li>字符</li></ul><p>参考：<a href="https://netguru.co/blog/photoshop-for-front-end-developers" target="_blank" rel="noreferrer">The Ultimate Front-End Developer&#39;s Guide to Photoshop</a></p><h2 id="切图" tabindex="-1">切图 <a class="header-anchor" href="#切图" aria-label="Permalink to &quot;切图&quot;">​</a></h2><ul><li>选“类型”-“图片”过滤出待切图层，用 <a href="https://github.com/jwa107/Photoshop-Export-Layers-to-Files-Fast/" target="_blank" rel="noreferrer">Export-Layers-to-Files-Fast</a> 导出</li><li>在图层上右键复制CSS，可更快获取字体字号、颜色等属性</li><li>手动切图： <ol><li>将待切元素拖放到新页面 （背景透明）</li><li>自动裁切，去掉多余部分</li></ol></li></ul><p>Tips：PS自带功能“将图层导出到文件”的脚本也不错，用前把待导出图片最好放到一个新画布</p><p><img src="https://img.oaker.bid/?url=http://ww2.sinaimg.cn/large/4e5d3ea7jw1ex0m7pll8jj20vu0p5guz.jpg" alt=""></p><h2 id="切片" tabindex="-1">切片 <a class="header-anchor" href="#切片" aria-label="Permalink to &quot;切片&quot;">​</a></h2><ul><li>裁剪 --&gt; 切片</li><li>可对切片设置属性</li><li>按Shift键多选，组合切片</li><li>在导出到文件对话框中，可选择“HTML和图象”</li></ul><p>参考：<a href="http://www.shejipai.cn/image-slicing-photoshop.html" target="_blank" rel="noreferrer">设计派 | 如何正确使用Photoshop切片工具</a></p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><table><thead><tr><th>功能</th><th style="text-align:center;">快捷键</th></tr></thead><tbody><tr><td>改变视图</td><td style="text-align:center;">Ctrl/Alt + 滚轮、左右键</td></tr><tr><td>拖动（抓手工具<code>H</code>）</td><td style="text-align:center;">空格 + 左键</td></tr></tbody></table><p><img src="https://cloud.githubusercontent.com/assets/3146103/8339663/b37fdece-1aeb-11e5-9c29-408a710ff76d.png" alt="image"></p><p>自由的控制视图系列</p><ul><li>自由的浏览图片：按住空格后，鼠标拖动</li><li>自由的缩放图片：按住alt+滚轮</li><li>切换到实际像素（100%）：Ctrl + 1</li><li>工作区类型切换：Tab</li></ul><p>控制内容系列</p><ul><li>通过画面上点选一个图层：Alt + 鼠标右键</li><li>在画面上拖动一个图层：V 切换到移动模式 鼠标拖动</li><li>复制拖动一个图层：移动模式下 Alt+拖动</li><li>删除一个图层：选中要删除的图层 按下 Delete</li><li>合并多个图层：选中要合并的图层 按下 Ctrl+E</li><li>选区内填充颜色：Alt+Delete (前景色) Ctrl+Delete(背景色)</li><li>缩放当前选择图层：Ctrl+T(自由变换模式)</li></ul><p>实用工具系列</p><ul><li>画一个选区：点击M进入选区模式 ， 鼠标拖画</li><li>放弃选区：Ctrl+D</li><li>吸管工具：点击I进入吸管模式，点选画面颜色</li><li>文字工具：点击T进入文字模式，点选画面的文字或者创建新文本</li><li>切片工具：点击C进入切片模式（旧版本会有不同）</li></ul>',21),r=[a];function h(s,p,n,d,c,u){return e(),l("div",null,r)}const m=t(i,[["render",h]]);export{f as __pageData,m as default};
